CREATE TABLE public.fishing_regulations (
    id integer NOT NULL,
    state text NOT NULL,
    state_abbr text NOT NULL,
    species text NOT NULL,
    daily_bag_limit integer,
    possession_limit integer,
    size_limit_inches numeric(5,1),
    slot_limit_min numeric(5,1),
    slot_limit_max numeric(5,1),
    season_open text,
    season_close text,
    season_notes text,
    special_rules text,
    water_body_type text DEFAULT 'all'::text NOT NULL,
    water_body_name text,
    catch_and_release_only boolean DEFAULT false,
    artificial_lures_only boolean DEFAULT false,
    barbless_hooks_required boolean DEFAULT false,
    updated_at timestamp with time zone DEFAULT now()
);

CREATE SEQUENCE public.fishing_regulations_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
    
ALTER SEQUENCE public.fishing_regulations_id_seq OWNED BY public.fishing_regulations.id;


ALTER TABLE ONLY public.fishing_regulations ALTER COLUMN id SET DEFAULT nextval('public.fishing_regulations_id_seq'::regclass);

ALTER TABLE ONLY public.fishing_regulations ADD CONSTRAINT fishing_regulations_pkey PRIMARY KEY (id);

CREATE INDEX idx_fishing_regulations_species ON public.fishing_regulations USING btree (species);

CREATE INDEX idx_fishing_regulations_state ON public.fishing_regulations USING btree (state);

CREATE INDEX idx_fishing_regulations_water_body ON public.fishing_regulations USING btree (water_body_type);

SELECT setval('public.fishing_regulations_id_seq', COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM public.fishing_regulations;
